            "name": "schema_report",
            "typeName": "Record"
          }
        },
        {
          "name": "detect_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Detect data-quality issues like schema drift, missing values, and duplicates.",
          "inputBindings": [
            {
              "param": "schema",
              "source": "inspect_schema",
              "binding": "schema_report"
            }
          ],
          "code": "import pandas as pd\ndf = pd.read_csv('${item}')\nschema = ${schema}\nissues = []\nmissing = df.isnull().sum()\nfor col, count in missing.items():\n    if count > 0:\n        issues.append(f\"Missing values in {col}: {count}\")\nduplicates = df.duplicated().sum()\nif duplicates > 0:\n    issues.append(f\"Duplicate rows: {duplicates}\")\nexpected_cols = [c['name'] for c in schema['columns']]\nif list(df.columns) != expected_cols:\n    issues.append(f\"Schema drift detected. Expected {expected_cols}, got {list(df.columns)}\")\nenv[\"issues_report\"] = {\"issues\": issues, \"columns\": list(df.columns), \"row_count\": len(df)}",
          "output": {
            "name": "issues_report",
            "typeName": "Record"
          }
        },
        {
          "name": "repair_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Repair recoverable data-quality issues such as missing values and duplicates.",
          "inputBindings": [
            {
              "param": "issues",
              "source": "detect_issues",
              "binding": "issues_report"
            }
          ],
          "code": "import pandas as pd\ndf = pd.read_csv('${item}')\nissues = ${issues}\ndf = df.drop_duplicates()\nfor col in df.columns:\n    if df[col].isnull().any():\n        if df[col].dtype in ['int64', 'float64']:\n            df[col] = df[col].fillna(df[col].mean())\n        else:\n            df[col] = df[col].fillna(df[col].mode()[0] if not df[col].mode().empty else 'UNKNOWN')\nrepaired_path = '${item}.repaired.csv'\ndf.to_csv(repaired_path, index=False)\nenv[\"repaired_file\"] = repaired_path",
          "output": {
            "name": "repaired_file",
            "typeName": "String"
          }
        },
        {
          "name": "revalidate",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Revalidate the repaired data to ensure issues are resolved.",
          "inputBindings": [
            {
              "param": "repaired_file",
              "source": "repair_issues",
              "binding": "repaired_file"
            }
          ],
          "code": "import pandas as pd\ndf = pd.read_csv('${repaired_file}')\nvalidation_errors = []\nmissing = df.isnull().sum()\nfor col, count in missing.items():\n    if count > 0:\n        validation_errors.append(f\"Still missing values in {col}: {count}\")\nduplicates = df.duplicated().sum()\nif duplicates > 0:\n    validation_errors.append(f\"Still duplicate rows: {duplicates}\")\nenv[\"validation_report\"] = {\"errors\": validation_errors, \"is_valid\": len(validation_errors) == 0}",
          "output": {
            "name": "validation_report",
            "typeName": "Record"
          }
        },
        {
          "name": "compute_stats",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Compute quarterly statistics and detect outliers.",
