            {
              "param": "repaired_file",
              "source": "repair_issues",
              "binding": "repaired_file"
            }
          ],
          "code": "import pandas as pd\ndf = pd.read_csv('${repaired_file}')\nstats = {}\nfor col in df.columns:\n    if df[col].dtype in ['int64', 'float64']:\n        stats[col] = {\"mean\": df[col].mean(), \"sum\": df[col].sum(), \"min\": df[col].min(), \"max\": df[col].max()}\nfor col in df.columns:\n    if df[col].dtype in ['int64', 'float64']:\n        Q1 = df[col].quantile(0.25)\n        Q3 = df[col].quantile(0.75)\n        IQR = Q3 - Q1\n        outliers = df[(df[col] < (Q1 - 1.5 * IQR)) | (df[col] > (Q3 + 1.5 * IQR))]\n        if col not in stats:\n            stats[col] = {}\n        stats[col][\"outlier_count\"] = len(outliers)\nenv[\"quarterly_stats\"] = stats",
