        {
          "param": "quality_report",
          "source": "quality_review",
          "binding": "quality_report"
        }
      ],
      "code": "merged_data = ${merged_data}\nquality_report = ${quality_report}\nmd = \"# Consolidated Quarterly Sales Report\\n\\n\"\nmd += \"## Quality Review\\n\"\nfor comment in quality_report['review_comments']:\n    md += f\"- {comment}\\n\"\nmd += f\"\\nTotal Issues Detected: {quality_report['total_issues']}\\n\\n\"\nmd += \"## Evidence Log\\n\"\nfor log in merged_data['evidence_log']:\n    md += f\"- File: {log.get('file', 'unknown')}, Issues: {log['issues']}\\n\"\nmd += \"\\n## Aggregated Statistics\\n\"\nfor col, stats_list in merged_data['stats'].items():\n    md += f\"\\n### {col}\\n\"\n    for i, s in enumerate(stats_list):\n        md += f\"- Q{i+1}: {s}\\n\"\nenv[\"final_report\"] = md",
      "output": {
        "name": "final_report",
        "typeName": "String"
      }
